// Install required packages
// npm install express-session cookie-parser helmet

const express = require('express');
const session = require('express-session');
const cookieParser = require('cookie-parser');
const helmet = require('helmet');

const app = express();

// Use helmet for security headers
app.use(helmet());

// Configure session with secure cookies
app.use(session({
  secret: process.env.SESSION_SECRET,
  name: 'sessionId', // Custom name (not 'connect.sid')
  cookie: {
    secure: true,      // Only send over HTTPS
    httpOnly: true,    // Prevent JavaScript access
    sameSite: 'strict', // Prevent CSRF
    maxAge: 3600000,   // 1 hour
    domain: 'example.com',
    path: '/'
  },
  resave: false,
  saveUninitialized: false
}));

// Configure cookie parser
app.use(cookieParser());

// Set custom cookie with security flags
app.get('/set-cookie', (req, res) => {
  res.cookie('customCookie', 'value', {
    httpOnly: true,
    secure: true,
    sameSite: 'strict',
    maxAge: 3600000,
    path: '/'
  });
  res.send('Secure cookie set');
});

// Environment-aware configuration
const isProduction = process.env.NODE_ENV === 'production';
if (isProduction) {
  app.set('trust proxy', 1); // Trust first proxy for secure cookies
}

app.listen(3000);

