      .get('/login')
      .expect(200);

    const setCookieHeader = response.headers['set-cookie'][0];
    expect(setCookieHeader).toMatch(/HttpOnly/);
    expect(setCookieHeader).toMatch(/Secure/);
    expect(setCookieHeader).toMatch(/SameSite=Strict/i);
  });

  test('Custom cookie has all security flags', async () => {
    const response = await request(app)
      .get('/set-cookie')
      .expect(200);

    const cookie = response.headers['set-cookie']
      .find(c => c.startsWith('customCookie'));

    expect(cookie).toBeDefined();
    expect(cookie).toMatch(/HttpOnly/);
    expect(cookie).toMatch(/Secure/);
    expect(cookie).toMatch(/SameSite=Strict/i);
  });
});

