using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;

public class CookieSecurityTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly WebApplicationFactory<Program> _factory;

    public CookieSecurityTests(WebApplicationFactory<Program> factory)
    {
        _factory = factory;
    }

    [Fact]
    public async Task SessionCookie_HasSecurityAttributes()
    {
        var client = _factory.CreateClient();
        var response = await client.GetAsync("/login");

        Assert.True(response.Headers.TryGetValues("Set-Cookie", 
            out var cookies));

        var sessionCookie = cookies.FirstOrDefault(c => 
            c.Contains(".MyApp.Session"));

        Assert.NotNull(sessionCookie);
        Assert.Contains("HttpOnly", sessionCookie);
        Assert.Contains("Secure", sessionCookie);
        Assert.Contains("SameSite=Strict", sessionCookie);
    }
}

