// Java Selenium Example
import org.openqa.selenium.Cookie;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class CookieSecurityTest {

    @Test
    public void testCookieSecurityAttributes() {
        WebDriver driver = new ChromeDriver();
        driver.get("https://example.com/login");

        // Login to create session cookie
        // ... perform login ...

        // Get all cookies
        Set<Cookie> cookies = driver.manage().getCookies();

        // Find session cookie
        Cookie sessionCookie = cookies.stream()
            .filter(c -> c.getName().equals("JSESSIONID"))
            .findFirst()
            .orElse(null);

        assertNotNull(sessionCookie, "Session cookie not found");
        assertTrue(sessionCookie.isSecure(), 
            "Cookie missing Secure flag");
        assertTrue(sessionCookie.isHttpOnly(), 
            "Cookie missing HttpOnly flag");
        // Note: Selenium doesn't expose SameSite, use HTTP header inspection

        driver.quit();
    }
}
